--
-- Name: auto_generate_netdoc_id(); Type: FUNCTION; Schema: public; Owner: netaris
--

CREATE FUNCTION public.auto_generate_netdoc_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.id IS NULL OR NEW.id = '' THEN
        NEW.id := find_earliest_netdoc_id();
    END IF;
    RETURN NEW;
END;
$$;


